&lt;td&gt;Cerebras&lt;/td&gt;
&lt;td&gt;Llama 3.1 70B / 8B&lt;/td&gt;
&lt;td&gt;30 RPM，60K TPM，1M tokens/天&lt;/td&gt;
&lt;td&gt;否&lt;/td&gt;
&lt;td&gt;超长上下文&lt;/td&gt;
&lt;/tr&gt;
